                   <div className="w-11 h-6 bg-trip-primary rounded-full peer"></div>
                   <div className="absolute left-[2px] top-[2px] bg-white border border-gray-300 rounded-full h-5 w-5 transition-all translate-x-full"></div>
                </div>
              </div>

