              Destinos
            </a>
            <a 
              href="#" 
              onClick={(e) => handlePageNavigation(e, 'about')}
              className="text-gray-600 hover:text-trip-primary font-medium transition-colors cursor-pointer"
            >
              Nosotros
            </a>
            <a 
              href="#reviews" 
              onClick={(e) => handleNavigation(e, 'reviews')}
