                 </div>

                 <div className="grid grid-cols-1 md:grid-cols-3 gap-6 md:gap-8">
                    <div className="bg-gray-50 p-6 md:p-8 rounded-3xl md:rounded-[2rem] hover:bg-trip-primary hover:text-white group transition-all duration-300">
