// === RENDER DESTINATIONS ===
function renderDestinations() {
    const grid = document.getElementById('destinations-grid');
    const dropdown = document.getElementById('hero-dropdown');

    // Grid
    grid.innerHTML = destinations.map(dest => `
        <div onclick="openDetailModal(${dest.id})" class="relative group bg-white rounded-3xl shadow-md hover:shadow-2xl transition-all duration-500 transform hover:-translate-y-2 cursor-pointer border border-transparent hover:border-trip-ice flex flex-col h-full">
            <div class="relative h-64 overflow-hidden rounded-t-3xl">
                <img src="${dest.image}" alt="${dest.title}" class="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" />
                <div class="absolute top-4 right-4 bg-white/90 backdrop-blur px-3 py-1 rounded-full text-xs font-bold text-trip-black flex items-center gap-1 shadow-sm">
                    ⭐ ${dest.rating}
                </div>
            </div>
            <div class="p-6 flex flex-col flex-1">
                <div class="flex justify-between items-start mb-auto">
                    <div>
                        <h4 class="text-xl font-bold text-trip-black mb-1">${dest.title}</h4>
                        <p class="text-gray-500 flex items-center gap-1 text-sm mt-1">🕒 ${dest.days} ${dest.days === 1 ? 'Día' : 'Días'}</p>
                    </div>
                    <div class="text-right">
                        <p class="text-xs text-gray-400">Desde</p>
                        <p class="text-xl font-bold text-trip-primary">${dest.price}€</p>
                    </div>
                </div>
                <div class="flex items-center justify-between pt-4 mt-4 border-t border-gray-100">
                    <span class="text-sm font-medium text-gray-500 flex items-center gap-2">📅 ${dest.location}</span>
                    <span class="text-trip-black font-semibold text-sm hover:text-trip-primary transition-colors">Más info</span>
                </div>
            </div>
        </div>
    `).join('');

    // Hero Dropdown
    dropdown.innerHTML = destinations.map(dest => `
        <div onclick="selectHeroDestination(${dest.id})" class="flex items-center gap-3 p-3 hover:bg-trip-ice transition-colors cursor-pointer border-b border-gray-50 last:border-0">
            <img src="${dest.image}" class="w-10 h-10 rounded-lg object-cover" />
            <div>
                <p class="text-sm font-bold text-trip-black truncate">${dest.title}</p>
                <p class="text-xs text-gray-500">${dest.location}</p>
            </div>
        </div>
    `).join('');
}

// === IMAGE GALLERY (Infinite Loop) ===
function renderGallery() {
    const scroller = document.getElementById('gallery-scroller');
    // Triple the images for smoother seamless loop
    const images = [...galleryImages, ...galleryImages, ...galleryImages];

    scroller.innerHTML = images.map(src => `
        <div class="relative h-64 w-48 md:h-80 md:w-64 flex-shrink-0 rounded-2xl overflow-hidden shadow-lg border-2 border-white">
            <img src="${src}" loading="lazy" class="h-full w-full object-cover pointer-events-none" />
        </div>
    `).join('');

    // Auto Scroll Logic
    let scrollPos = 0;
    const speed = 0.5;

    function animate() {
        scrollPos += speed;
        if (scrollPos >= scroller.scrollWidth / 3) {
            scrollPos = 0;
        }
        scroller.scrollLeft = scrollPos;
        requestAnimationFrame(animate);
    }
    requestAnimationFrame(animate);
}

// === MODALS ===
window.openBookingModal = (interest = '') => {
    window.currentInterest = interest;
    const modal = document.getElementById('booking-modal');
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    document.body.style.overflow = 'hidden';
};

window.openCalendarModal = () => {
    const modal = document.getElementById('calendar-modal');
    const content = document.getElementById('calendar-content');

    // Group by month logic
    const grouped = {};
    destinations.forEach(d => {
        const month = d.location.split(' ').pop();
        if(!grouped[month]) grouped[month] = [];
        grouped[month].push(d);
    });

    content.innerHTML = Object.keys(grouped).map(month => `
        <div class="animate-fade-in">
            <h3 class="text-2xl font-bold text-trip-black capitalize mb-4">${month}</h3>
            <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
                ${grouped[month].map(dest => `
                    <div onclick="closeModal('calendar-modal'); openBookingModal('${dest.title}')" class="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm hover:shadow-md cursor-pointer flex items-center gap-4">
                        <img src="${dest.image}" class="w-16 h-16 rounded-xl object-cover" />
                        <div class="flex-1">
                            <h4 class="font-bold text-trip-black">${dest.title}</h4>
                            <p class="text-xs text-gray-500">${dest.location}</p>
                        </div>
                        <span class="text-trip-primary font-bold">${dest.price}€</span>
                    </div>
                `).join('')}
            </div>
        </div>
    `).join('');

    modal.classList.remove('hidden');
    modal.classList.add('flex');
    document.body.style.overflow = 'hidden';
    lucide.createIcons();
};

window.openDetailModal = (id) => {
    const dest = destinations.find(d => d.id === id);
    if (!dest) return;

    document.getElementById('detail-img').src = dest.image;
    document.getElementById('detail-title').innerText = dest.title;
    document.getElementById('detail-price').innerText = dest.price + '€';
    document.getElementById('detail-date').innerText = '📅 ' + dest.location;
    document.getElementById('detail-desc').innerText = dest.description;

    const modal = document.getElementById('detail-modal');
    modal.classList.remove('hidden');
    modal.classList.add('flex');
    document.body.style.overflow = 'hidden';
};

window.closeModal = (id) => {
    const modal = document.getElementById(id);
    modal.classList.add('hidden');
    modal.classList.remove('flex');
    document.body.style.overflow = 'auto';
};

window.redirectToWhatsApp = () => {
    const phone = "34649866985";
    const text = window.currentInterest 
        ? `Hola, me interesa reservar: ${window.currentInterest}` 
        : "Hola, quiero información sobre un viaje.";
    window.open(`https://wa.me/${phone}?text=${encodeURIComponent(text)}`, '_blank');
    closeModal('booking-modal');
};

