};

// === AI PLANNER (GEMINI) ===
window.generateItinerary = async () => {
    const prompt = document.getElementById('ai-prompt').value;
    if (!prompt) return;

    const btnIcon = document.getElementById('ai-btn-icon');
    const loader = document.getElementById('ai-loader');
    const resultDiv = document.getElementById('ai-result-content');
    const placeholder = document.getElementById('ai-result-placeholder');

    // UI Loading
    btnIcon.classList.add('hidden');
    loader.classList.remove('hidden');

    try {
        const ai = new GoogleGenAI({ apiKey: API_KEY });
        const response = await ai.models.generateContent({
            model: 'gemini-1.5-flash',
            contents: {
                role: 'user',
                parts: [{ text: `Eres Tereviajes AI. Crea un itinerario breve con emojis para: ${prompt}` }]
            }
        });

        const text = response.text();

        // Render Markdown
        placeholder.classList.add('hidden');
        resultDiv.classList.remove('hidden');
        resultDiv.innerHTML = marked.parse(text);

    } catch (error) {
        console.error(error);
        alert("Error: Verifica tu API KEY en el script.js");
    } finally {
        btnIcon.classList.remove('hidden');
        loader.classList.add('hidden');
    }
};

// === UTILS ===
function initTypingEffect() {
    const phrases = ["Sueña", "Elige", "Realiza"];
    let i = 0;
    let j = 0;
    let isDeleting = false;
    const el = document.getElementById('hero-typing');

    function loop() {
        const current = phrases[i];
        if (isDeleting) {
            el.innerText = current.substring(0, j - 1);
            j--;
            if (j === 0) { isDeleting = false; i = (i + 1) % phrases.length; }
        } else {
            el.innerText = current.substring(0, j + 1);
            j++;
            if (j === current.length) { isDeleting = true; setTimeout(loop, 2000); return; }
        }
        setTimeout(loop, isDeleting ? 50 : 150);
    }
    loop();
}

function initMobileMenu() {
    const btn = document.getElementById('mobile-menu-btn');
    const menu = document.getElementById('mobile-menu');
    btn.addEventListener('click', () => {
        menu.classList.toggle('hidden');
    });
}

function setupOutsideClicks() {
    document.addEventListener('click', (e) => {
        const dd = document.getElementById('hero-dropdown');
        const trigger = e.target.closest('[onclick="toggleDestinationDropdown()"]');
        if (!trigger && !e.target.closest('#hero-dropdown')) {
            dd.classList.add('hidden');
        }
    });
}
